Customer "1" -- "0..*" RefuelCard : holds
Customer "1" -- "0..*" Invoice : receives
Invoice "1" -- "0..*" Payment : settled by
Invoice "1" -- "*" RefuelTurn : includes
GasStation "1" -- "*" DailyReport : produces
DailyReport "1" -- "*" Pump : reports

@enduml

